    "code": "```java\nvoid testAbandonedStackTraces() throws Exception  {\n    // force abandoned ds.setRemoveAbandonedTimeout(Duration.ZERO);\n    ds.setMaxTotal(1);\n    ds.setAccessToUnderlyingConnectionAllowed(true);\n    ds.setAbandonedUsageTracking(true);\n    try (Connection conn1 = getConnection())\n    {\n        assertNotNull(conn1);\n        assertEquals(1, ds.getNumActive());\n        // Use the connection try (Statement stmt = conn1.createStatement())\n        {\n            assertNotNull(stmt);\n            stmt.execute(\"SELECT 1 FROM DUAL\");\n        }\n        try (Connection conn2 = getConnection())\n        {\n            // Attempt to borrow object triggers abandoned cleanup // conn1 should be closed by the pool to make room assertNotNull(conn2);\n            assertEquals(1, ds.getNumActive());\n            // Verify that conn1 is closed assertTrue(((DelegatingConnection<?>) conn1).getInnermostDelegate().isClosed());\n            // Verify that conn1 is aborted final TesterConnection tCon = (TesterConnection) ((DelegatingConnection<?>) conn1).getInnermostDelegate();\n            assertTrue(tCon.isAborted());\n        }\n        assertEquals(0, ds.getNumActive());\n    }\n    assertEquals(0, ds.getNumActive());\n    final String stackTrace = sw.toString();\n    assertTrue(stackTrace.contains(\"testAbandonedStackTraces\"), stackTrace);\n    assertTrue(stackTrace.contains(\"Pooled object created\"), stackTrace);\n    assertTrue(stackTrace.contains(\"The last code to use this object was:\"), stackTrace);\n}\n```"
