protected void passivate() throws SQLException  {
    // The JDBC specification requires that a Connection close any open // Statements when it is closed. // DBCP-288. Not all the traced objects will be statements final List<AbandonedTrace> traceList = getTrace();
    if (!Utils.isEmpty(traceList))
    {
        final List<Exception> thrownList = new ArrayList<>();
        traceList.forEach(trace -> trace.close(thrownList::add));
        clearTrace();
        if (!thrownList.isEmpty())
        {
            throw new SQLExceptionList(thrownList);
        }
    }
    setLastUsed(Instant.EPOCH);
}
