ry);\n    }\n    catch (final RuntimeException e)\n    {\n        throw e;\n    }\n    catch (final Exception e)\n    {\n        throw new SQLException(\"Cannot create PoolableConnectionFactory (\" + e.getMessage() + \")\", e);\n    }\n    return connectionFactory;\n}\n```"
