public int[] batch(final Connection conn, final String sql, final Object[][] params) throws SQLException  {
    if (conn == null)
    {
        throw new SQLException("Null connection");
    }
    if (sql == null)
    {
        throw new SQLException("Null SQL statement");
    }
    if (params == null)
    {
        throw new SQLException("Null parameters. If parameters aren't need, pass an empty array.");
    }
    PreparedStatement stmt = null;
    ParameterMetaData pmd = null;
    int[] rows = null;
    try
    {
        stmt = this.prepareStatement(conn, sql);
        // When the batch size is large, prefetching parameter metadata before filling // the statement can reduce lots of JDBC communications. pmd = getParameterMetaData(stmt);
        for (final Object[] param : params)
        {
            this.fillStatement(stmt, pmd, param);
            stmt.addBatch();
        }
        rows = stmt.executeBatch();
    }
    catch (final SQLException e)
    {
        rethrow(e, sql, (Object[])params);
    }
    finally
    {
        close(stmt);
    }
    return rows;
}
