private void stop(final Thread thread, final Duration timeout)  {
    if (thread != null)
    {
        try
        {
            if (timeout.equals(Duration.ZERO))
            {
                thread.join();
            }
            else
            {
                final Duration timeToWait = timeout.plus(STOP_TIMEOUT_ADDITION);
                final Instant startTime = Instant.now();
