private static String[] translateCommandline(final String toProcess)  {
    if (toProcess == null || toProcess.trim().isEmpty())
    {
        // no command? no string return new String[0];
    }
    // parse with a simple finite state machine. final int normal = 0;
    final int inQuote = 1;
    final int inDoubleQuote = 2;
    int state = normal;
    final StringTokenizer tok = new StringTokenizer(toProcess, "\"\' ", true);
    final ArrayList<String> list = new ArrayList<>();
    StringBuilder current = new StringBuilder();
    boolean lastTokenHasBeenQuoted = false;
    while (tok.hasMoreTokens())
    {
        final String nextTok = tok.nextToken();
        switch (state)
        {
            case inQuote: if ("\'".equals(nextTok))
            {
                lastTokenHasBeenQuoted = true;
                state = normal;
            }
            else
            {
                current.append(nextTok);
            }
            break;
            case inDoubleQuote: if ("\"".equals(nextTok))
            {
                lastTokenHasBeenQuoted = true;
                state = normal;
            }
            else
            {
                current.append(nextTok);
            }
            break;
            default: switch (nextTok)
            {
                case "\'": state = inQuote;
                break;
                case "\"": state = inDoubleQuote;
                break;
                case " ": if (lastTokenHasBeenQuoted || current.length() != 0)
                {
                    list.add(current.toString());
                    current = new StringBuilder();
                }
                break;
                default: current.append(nextTok);
                break;
            }
            lastTokenHasBeenQuoted = false;
            break;
        }
    }
    if (lastTokenHasBeenQuoted || current.length() != 0)
    {
        list.add(current.toString());
    }
    if (state == inQuote || state == inDoubleQuote)
    {
        throw new IllegalArgumentException("Unbalanced quotes in " + toProcess);
    }
    final String[] args = new String[list.size()];
    return list.toArray(args);
}
